import java.util.*;
import java.io.*;

public class Main {
    static long[] process(long[] A, long[] B, long[][] ops) {
        // Write your solution here
        // ops[k] is {1, i, v} (set A[i] = v) or {2, x} (count pairs with sum x)
        return new long[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        long[] A = new long[n], B = new long[m];
        for (int i = 0; i < n; i++) { in.nextToken(); A[i] = (long) in.nval; }
        for (int j = 0; j < m; j++) { in.nextToken(); B[j] = (long) in.nval; }
        in.nextToken();
        int q = (int) in.nval;
        long[][] ops = new long[q][];
        for (int k = 0; k < q; k++) {
            in.nextToken();
            long t = (long) in.nval;
            if (t == 1) {
                in.nextToken(); long i = (long) in.nval;
                in.nextToken(); long v = (long) in.nval;
                ops[k] = new long[]{1, i, v};
            } else {
                in.nextToken(); long x = (long) in.nval;
                ops[k] = new long[]{2, x};
            }
        }
        long[] res = process(A, B, ops);
        StringBuilder sb = new StringBuilder();
        for (long r : res) sb.append(r).append('\n');
        System.out.print(sb);
    }
}

