def gen(rng):
    def fmt(A, B, ops):
        lines = [f'{len(A)} {len(B)}', ' '.join(map(str, A)), ' '.join(map(str, B)), str(len(ops))]
        for o in ops:
            lines.append(' '.join(map(str, o)))
        return '\n'.join(lines)
    def make(n, m, q, hi, qfrac, xhi=None):
        A = [rng.randint(1, hi) for _ in range(n)]
        B = [rng.randint(1, hi) for _ in range(m)]
        ops = []
        for k in range(q):
            if k == q - 1 or rng.random() < qfrac:
                if rng.random() < 0.7:
                    x = rng.choice(A) + rng.choice(B)
                else:
                    x = rng.randint(2, 2 * hi)
                ops.append((2, x))
            else:
                ops.append((1, rng.randrange(n), rng.randint(1, hi)))
        return fmt(A, B, ops)
